public StoredResponse rebind(String batchKey, RebindSpecRequest req) {
    fingerprint = fingerprint("rebind", batchKey, req.expectedVersion().toString(), req.newVersion().toString(), req.operator());
    return idempotent.execute(CMD_REBIND, req.requestId(), fingerprint, () -> {
        BatchRow batch = findBatchForUpdate or 404;
        logged recheck;
        lineage.assertNoRecalledAncestor(batchKey);
        if (batch.specKey() == null) throw unprocessable("批次未绑定特性规范，不能换版");
        BatchStatus status = valueOf;
        if (status != QUARANTINED && status != PENDING_RELEASE) throw conflict("批次状态 X 不允许换版，仅未放行批次可换版");
        if (!batchRepo.findApprovals(batchKey).isEmpty()) throw conflict("批次已存在批准，不能换版");
        if (batch.specVersion() != req.expectedVersion()) throw conflict("expectedVersion 与当前绑定版本不符: " + batch.specVersion());
        if (req.newVersion() == batch.specVersion()) throw badRequest("newVersion 与当前绑定版本相同");
        if (!specRepo.existsVersion(batch.specKey(), req.newVersion())) throw unprocessable("规范版本不存在");
        batchRepo.updateSpecVersion(batchKey, req.newVersion());
        BatchStatus newStatus = status;
        if (status == PENDING_RELEASE
            && specRepo.findPassMeasurement(batchKey, specKey, newVersion).isEmpty()) {
            newStatus = QUARANTINED;
            batchRepo.updateStatus(batchKey, QUARANTINED);
        }
        return 201 RebindSpecResponse;
    });
}
